function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  // Circle for unity
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  // Five lines for 5
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.moveTo(W/2 - 70, H/2 - 20 + i * 20);
    ctx.lineTo(W/2 - 30, H/2 - 20 + i * 20);
    ctx.stroke();
  }
  // One circle for 1
  ctx.beginPath();
  ctx.arc(W/2 + 60, H/2, 10, 0, 2 * Math.PI);
  ctx.stroke();
  // Eight petals for 8
  for (let i = 0; i < 8; i++) {
    ctx.beginPath();
    ctx.moveTo(W/2 + 100, H/2);
    ctx.lineTo(W/2 + 100 + 20 * Math.cos(i * Math.PI / 4 + t), H/2 + 20 * Math.sin(i * Math.PI / 4 + t));
    ctx.stroke();
  }
  ctx.restore();
}
